<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};

final class CompanyWorkspaceService
{
    use TenantOperations;
    public const CHECKS=['ACCOUNTS'=>'Review roles and recovery access','SITES'=>'Set up client sites and emergency contacts','ROSTER'=>'Configure staffing and training requirements','DEVICES'=>'Provision and test company phones','REPORTING'=>'Confirm client mappings and report delivery','BACKUP'=>'Record a successful restore test','ACCEPTANCE'=>'Complete a supervised operational trial'];
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly SubscriptionService $subscriptions) {}
    public function branding(): array {return $this->db->fetch('SELECT display_name,primary_color,logo_base64,logo_mime,support_contact,revision FROM company_workspace_profiles WHERE company_id=:company',['company'=>$this->company()])??['display_name'=>'Sentinel','primary_color'=>'#176b77','logo_base64'=>null,'logo_mime'=>null,'support_contact'=>'Contact your company control room.','revision'=>0];}
    public function saveBranding(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['expected_revision','display_name','primary_color','support_contact','logo_base64']);$old=$this->branding();if($this->number($input['expected_revision']??null,0)!==(int)$old['revision'])throw HttpException::conflict('Company branding changed.');$color=$input['primary_color']??null;if(!is_string($color)||!preg_match('/^#[a-f0-9]{6}$/Di',$color))throw HttpException::unprocessable('Choose a six-digit hexadecimal colour.');$logo=$old['logo_base64'];$mime=$old['logo_mime'];
        if(array_key_exists('logo_base64',$input)){if($input['logo_base64']===null||$input['logo_base64']===''){$logo=$mime=null;}else{if(!is_string($input['logo_base64'])||strlen($input['logo_base64'])>175000)throw HttpException::unprocessable('Logo exceeds 128 KiB.');$bytes=base64_decode($input['logo_base64'],true);$size=$bytes===false?false:@getimagesizefromstring($bytes);if(!$size||strlen($bytes)>131072||$size[0]>1024||$size[1]>1024||!in_array($size[2],[IMAGETYPE_PNG,IMAGETYPE_JPEG],true))throw HttpException::unprocessable('Use a PNG/JPEG logo up to 128 KiB and 1024 pixels per side.');$logo=base64_encode($bytes);$mime=$size[2]===IMAGETYPE_PNG?'image/png':'image/jpeg';}}
        $values=['company'=>$this->company(),'name'=>$this->text($input['display_name']??null,150),'color'=>strtolower($color),'logo'=>$logo,'mime'=>$mime,'contact'=>$this->text($input['support_contact']??null,300),'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')];
        if((int)$old['revision']===0)$this->db->execute('INSERT INTO company_workspace_profiles(company_id,display_name,primary_color,logo_base64,logo_mime,support_contact,updated_by_user_id,updated_at) VALUES(:company,:name,:color,:logo,:mime,:contact,:actor,:now)',$values);else $this->db->execute('UPDATE company_workspace_profiles SET display_name=:name,primary_color=:color,logo_base64=:logo,logo_mime=:mime,support_contact=:contact,revision=revision+1,updated_by_user_id=:actor,updated_at=:now WHERE company_id=:company',$values);
        $this->audit->record('company_workspace','branding_saved',(string)$this->company());return ['revision'=>(int)$old['revision']+1];
    });}
    public function overview(): array {
        $subscription=$this->subscriptions->current();$plan=$subscription['plan_code']??null;$limits=$plan!==null?(SubscriptionPolicy::plans()[$plan]['limits']??null):null;
        $users=(int)$this->db->fetch("SELECT COUNT(*) AS n FROM users WHERE company_id=:company AND status<>'ARCHIVED'",['company'=>$this->company()])['n'];$sites=$this->db->fetchAll('SELECT * FROM sites WHERE company_id=:company',['company'=>$this->company()]);$count=count(array_filter($sites,static fn($s)=>!in_array($s['status']??'ACTIVE',['CLOSED','INACTIVE'],true)));
        $checks=$this->db->fetchAll('SELECT check_code,evidence_reference,completed_by_user_id,completed_at FROM company_setup_checks WHERE company_id=:company ORDER BY check_id',['company'=>$this->company()]);
        return ['subscription'=>$subscription,'plans'=>SubscriptionPolicy::plans(),'usage'=>['users'=>$users,'sites'=>$count],'limits'=>$limits,'remaining'=>['users'=>$limits!==null&&$limits['users']!==null?max(0,$limits['users']-$users):null,'sites'=>$limits!==null&&$limits['sites']!==null?max(0,$limits['sites']-$count):null],'setup_steps'=>self::CHECKS,'completed_checks'=>$checks,'change_requests'=>$this->db->fetchAll('SELECT * FROM subscription_change_requests WHERE company_id=:company ORDER BY request_id DESC LIMIT 100',['company'=>$this->company()]),'note'=>'Plan changes are requests for account administration. This screen does not take payments or activate paid plans. Setup records are staff attestations with evidence references.'];
    }
    public function completeCheck(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['check_code','evidence_reference']);$code=$input['check_code']??null;if(!is_string($code)||!isset(self::CHECKS[$code]))throw HttpException::unprocessable('Choose a known setup step.');$keys=['company'=>$this->company(),'code'=>$code];$reference=$this->text($input['evidence_reference']??null,1000);$old=$this->db->fetch('SELECT check_id FROM company_setup_checks WHERE company_id=:company AND check_code=:code',$keys);if($old)throw HttpException::conflict('Setup check already recorded. Reopen it before recording new evidence.');$this->db->execute('INSERT INTO company_setup_checks(company_id,check_code,evidence_reference,completed_by_user_id,completed_at) VALUES(:company,:code,:reference,:actor,:now)',$keys+['reference'=>$reference,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('company_setup_check');
    });}
    public function reopenCheck(string $code): array {return $this->atomic(function()use($code){if(!isset(self::CHECKS[$code]))throw HttpException::notFound();$old=$this->db->fetch('SELECT * FROM company_setup_checks WHERE company_id=:company AND check_code=:code',['company'=>$this->company(),'code'=>$code]);$this->db->execute('DELETE FROM company_setup_checks WHERE company_id=:company AND check_code=:code',['company'=>$this->company(),'code'=>$code]);$this->audit->record('company_setup_check','reopened',$code,$old??[]);return ['reopened'=>true];});}
    public function requestPlan(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['target_plan','notes']);$plan=$input['target_plan']??null;if(!is_string($plan)||!SubscriptionPolicy::isKnownPlan($plan))throw HttpException::unprocessable('Choose a known plan.');if($this->db->fetch("SELECT request_id FROM subscription_change_requests WHERE company_id=:company AND state='REQUESTED'",['company'=>$this->company()]))throw HttpException::conflict('An account change request is already pending.');$this->db->execute('INSERT INTO subscription_change_requests(company_id,target_plan,notes,requested_by_user_id,requested_at) VALUES(:company,:plan,:notes,:actor,:now)',['company'=>$this->company(),'plan'=>$plan,'notes'=>$this->text($input['notes']??null,1000),'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('subscription_change_request');
    });}
    public function cancelPlan(string $id): array {return $this->atomic(function()use($id){$r=$this->row('subscription_change_requests','request_id',$id);if($r['state']!=='REQUESTED')throw HttpException::conflict('Request is no longer pending.');$this->db->execute("UPDATE subscription_change_requests SET state='CANCELLED',cancelled_at=:now WHERE company_id=:company AND request_id=:id",['now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$id]);$this->audit->record('subscription_change_request','cancelled',$id);return ['cancelled'=>true];});}
}
